    def __init__(self, errors: Sequence[Any], *, context: Optional[Dict[str, Any]] = None) -> None:
        super().__init__(errors)
        self.context = context

    def __str__(self) -> str:
        message = f"{len(self._errors)} validation errors:\\n"
        for err in self._errors:
            message += f"  {err}\\n"
        if self.context:
            message += f"\\n\\nEndpoint Context:\\n"
            message += f"  File: {self.context.get('filepath', 'N/A')}\\n"
            message += f"  Line: {self.context.get('lineno', 'N/A')}\\n"
            message += f"  Function: {self.context.get('func_name', 'N/A')}\\n"
            message += f"  Method: {self.context.get('method', 'N/A')}\\n"
            message += f"  Route: {self.context.get('route', 'N/A')}\\n"
        return message
